/**
 * Multi-language, multi-noise end-to-end suite for the Voice Khata voice WebSocket.
 *
 *   npx tsx --env-file=.env eval/e2e_suite.ts [url] [--noise none,street,cafeteria,babble,square]
 *        [--snr 10,5,0] [--langs hi,kn,ta,te] [--limit N] [--conc 4] [--yes-big] [--tag name]
 *
 * Default: all 4 languages, conditions = clean, street @ 5 dB, babble @ 5 dB.
 * Scenarios: eval/scenarios.json (generated by eval/make_scenarios.py).
 * Noise: eval/data/noise/{street,cafeteria,babble,square}.pcm (eval/prep_noise.py, sources in NOISE_SOURCES.md).
 * Shopkeeper speech: Gnani Timbre stock voice 'Avinash' (not the agent's voice), cached in eval/data/e2e_suite.
 * Noise is mixed at the given SNR (relative to the active-speech power of each clip) and keeps
 * streaming in the pauses and while the agent replies, at the same level: the mic is never silent.
 *
 * Outcomes per expected entry: direct_ok | asked_ok (agent asked, harness answered correctly) |
 * silent_wrong (saved wrong with no correct read-back in between: the worst failure) |
 * asked_wrong | no_save.
 */
import { createHash } from 'node:crypto'
import { existsSync, mkdirSync, readFileSync, writeFileSync } from 'node:fs'
import WebSocket from 'ws'
import type { LedgerOp, ServerMsg, Snapshot } from '../shared/protocol.js'

// ------------------------------------------------------------------ args
const argv = process.argv.slice(2)
const flag = (n: string) => argv.includes(`--${n}`)
const opt = (n: string, d: string): string => {
  const i = argv.indexOf(`--${n}`)
  return i >= 0 && argv[i + 1] ? argv[i + 1] : d
}
const optVals = new Set(['noise', 'snr', 'langs', 'limit', 'conc', 'tag'].map((n) => argv.indexOf(`--${n}`) + 1).filter((i) => i > 0))
const URL_ = argv.find((a, i) => !a.startsWith('--') && !optVals.has(i)) ?? 'wss://voice-khata-delta.vercel.app/api/voice'
const NOISES = opt('noise', 'none,street,babble').split(',')
const SNRS = opt('snr', '5').split(',').map(Number)
const LANGS = opt('langs', 'hi,kn,ta,te').split(',')
const LIMIT = Number(opt('limit', '0')) || Infinity
const CONC = Number(opt('conc', '4'))
const TAG = opt('tag', '')
const KEY = process.env.GNANI_API_KEY!
const VOICE = 'Avinash'
const CACHE = 'eval/data/e2e_suite'
mkdirSync(CACHE, { recursive: true })
mkdirSync('eval/results', { recursive: true })

interface Cond { noise: string; snr: number | null; label: string }
// "none" is a single clean condition; every real noise crosses with every SNR
const CONDS: Cond[] = NOISES.flatMap((n): Cond[] => (n === 'none' ? [{ noise: 'none', snr: null, label: 'clean' }] : SNRS.map((s) => ({ noise: n, snr: s, label: `${n} ${s}dB` }))))

// ------------------------------------------------------------------ scenarios
interface Expect {
  entries?: { cid: string; paise: number; direction: 'credit' | 'payment'; promise: boolean }[]
  amend?: { paise?: number; direction?: 'credit' | 'payment' }
  said?: string[]
  pending?: string
}
interface Scenario { id: string; kind: string; turns: { say: string; expect: Expect }[] }
interface LangSpec {
  locale: string; yes: string; no: string; dirCredit: string; dirPayment: string
  customers: { cid: string; name: string; aliases: string[]; balancePaise: number }[]
  scenarios: Scenario[]
}
const SC = JSON.parse(readFileSync('eval/scenarios.json', 'utf8')) as { shopName: string; langs: Record<string, LangSpec> }

const snapshotFor = (l: LangSpec): Snapshot => ({
  shopName: SC.shopName,
  customers: l.customers.map((c) => ({ cid: c.cid, name: c.name, aliases: c.aliases, householdId: null, remindersOptIn: false, adult: true, balancePaise: c.balancePaise, typicalPaise: null })),
  last: null,
  today: { creditPaise: 0, paymentPaise: 0, entries: 0 },
  month: { creditPaise: 0, paymentPaise: 0, entries: 0 },
})

// ------------------------------------------------------------------ TTS (cached)
const cacheFile = (text: string, locale: string) => `${CACHE}/${createHash('sha1').update(`${VOICE}|${locale}|${text}`).digest('hex').slice(0, 24)}.pcm`
async function synth(text: string, locale: string): Promise<Buffer> {
  const f = cacheFile(text, locale)
  if (existsSync(f)) return readFileSync(f)
  const parts: Buffer[] = []
  for (let attempt = 0; ; attempt++) {
    try {
      parts.length = 0
      await new Promise<void>((res, rej) => {
        const ws = new WebSocket('wss://api.vachana.ai/api/v1/tts', { headers: { 'X-API-Key-ID': KEY } })
        const to = setTimeout(() => { ws.close(); rej(new Error('tts timeout')) }, 30000)
        ws.on('open', () => ws.send(JSON.stringify({
          text, voice: VOICE, model: 'timbre-v3.0', language: locale,
          audio_config: { sample_rate: 16000, num_channels: 1, sample_width: 2, encoding: 'linear_pcm', container: 'raw' },
        })))
        ws.on('message', (d) => {
          const m = JSON.parse(d.toString())
          if (m.type === 'audio' && m.data?.audio) parts.push(Buffer.from(m.data.audio, 'base64'))
          if (m.type === 'complete' && m.message) { clearTimeout(to); ws.close(); res() }
        })
        ws.on('error', (e) => { clearTimeout(to); rej(e) })
      })
      break
    } catch (e) {
      if (attempt >= 2) throw e
    }
  }
  const pcm = trim(Buffer.concat(parts))
  if (pcm.length < 3200) throw new Error(`empty TTS for ${text}`)
  writeFileSync(f, pcm)
  return pcm
}
/** Trim the clip's own leading/trailing silence so "speech end" is exact. */
function trim(pcm: Buffer): Buffer {
  const n = pcm.length / 2
  const amp = (i: number) => Math.abs(pcm.readInt16LE(i * 2))
  let a = 0
  let b = n - 1
  while (a < n && amp(a) < 500) a++
  while (b > a && amp(b) < 500) b--
  return pcm.subarray(a * 2, (b + 1) * 2)
}

// ------------------------------------------------------------------ noise
const noiseCache = new Map<string, Int16Array>()
function loadNoise(name: string): Int16Array {
  let x = noiseCache.get(name)
  if (!x) {
    const f = `eval/data/noise/${name}.pcm`
    if (!existsSync(f)) throw new Error(`${f} missing: run python eval/prep_noise.py`)
    const b = readFileSync(f)
    x = new Int16Array(b.buffer.slice(b.byteOffset, b.byteOffset + b.length - (b.length % 2)))
    noiseCache.set(name, x)
  }
  return x
}
const power = (x: ArrayLike<number>) => { let s = 0; for (let i = 0; i < x.length; i++) s += x[i] * x[i]; return s / x.length }
const hash32 = (s: string) => { let h = 2166136261; for (let i = 0; i < s.length; i++) { h ^= s.charCodeAt(i); h = Math.imul(h, 16777619) } return h >>> 0 }

// ------------------------------------------------------------------ run one scenario
const FRAME = 1024
const FS = 512 // samples per frame
type Rec = { t: number; m: ServerMsg | { type: 'audio'; bytes: number } }
type Outcome = 'direct_ok' | 'asked_ok' | 'silent_wrong' | 'asked_wrong' | 'no_save' | 'ok' | 'fail' | 'skipped'

interface TurnResult {
  lang: string; cond: string; scenario: string; kind: string; turn: number
  say: string; heard: string[]; replied: string[]; asked: string[]
  expect: Expect; got: unknown
  outcome: Outcome; reason: string; latencyMs: number | null; snrDb: number | null
  entryOutcomes: Outcome[]
  dirOk: boolean[]
  kindOf: 'entry' | 'amend' | 'query' | 'pending'
}

const entryOf = (o: LedgerOp) => (o.op === 'entry' ? o : null)

async function runScenario(lang: string, spec: LangSpec, sc: Scenario, cond: Cond, tts: (t: string, l: string) => Promise<Buffer>): Promise<TurnResult[]> {
  const noise = cond.noise === 'none' ? null : loadNoise(cond.noise)
  const noiseP = noise ? power(noise) : 1
  let cursor = noise ? hash32(`${lang}|${sc.id}|${cond.label}`) % noise.length : 0
  let gain = 0

  // protected Vercel previews: the local development OIDC token passes Deployment Protection
  // (run under `vercel env run -- ...`; never printed)
  const oidc = process.env.VERCEL_OIDC_TOKEN
  const ws = new WebSocket(URL_, oidc && URL_.startsWith('wss://') ? { headers: { 'x-vercel-trusted-oidc-idp-token': oidc } } : undefined)
  const msgs: Rec[] = []
  ws.on('message', (d, bin) => msgs.push({ t: performance.now(), m: bin ? { type: 'audio', bytes: (d as Buffer).length } : JSON.parse(d.toString()) }))
  // E2E_DUMP=1: print every non-audio server message (debugging a deployment)
  if (process.env.E2E_DUMP) ws.on('message', (d, bin) => { if (!bin) console.log(`  [${lang} ${sc.id}] +${Math.round(performance.now() - t0)}ms ${d.toString().slice(0, 160)}`) })
  const t0 = performance.now()
  ws.on('error', (e) => msgs.push({ t: performance.now(), m: { type: 'error', message: String(e) } }))
  await new Promise<void>((res, rej) => { ws.on('open', () => res()); ws.on('error', rej) })
  ws.send(JSON.stringify({ type: 'hello', lang, snapshot: snapshotFor(spec), firstRun: false, ptt: false }))

  // one absolute clock for the whole scenario: the mic never stops
  const start = performance.now()
  let n = 0
  const sendFrame = async (speech: Buffer | null, off: number) => {
    const wait = start + n * 32 - performance.now()
    if (wait > 0) await new Promise((r) => setTimeout(r, wait))
    n++
    const out = new Int16Array(FS)
    if (speech) for (let i = 0; i < FS && off + i * 2 + 1 < speech.length; i++) out[i] = speech.readInt16LE(off + i * 2)
    if (noise) {
      for (let i = 0; i < FS; i++) {
        const v = out[i] + Math.round(noise[cursor] * gain)
        out[i] = v > 32767 ? 32767 : v < -32768 ? -32768 : v
        cursor = (cursor + 1) % noise.length
      }
    }
    if (ws.readyState === WebSocket.OPEN) ws.send(Buffer.from(out.buffer))
  }
  const pump = async (ms: number) => { for (let i = 0; i < Math.ceil(ms / 32); i++) await sendFrame(null, 0) }
  const speak = async (pcm: Buffer) => {
    if (noise) gain = Math.sqrt(power(new Int16Array(pcm.buffer.slice(pcm.byteOffset, pcm.byteOffset + pcm.length - (pcm.length % 2)))) / (noiseP * 10 ** (cond.snr! / 10)))
    for (let off = 0; off < pcm.length; off += FRAME) await sendFrame(pcm, off)
    return performance.now()
  }
  /** Say one utterance, then keep the room going until the reply is done. Returns the messages it produced. */
  const exchange = async (text: string): Promise<{ recs: Rec[]; speechEnd: number }> => {
    const pcm = await tts(text, spec.locale)
    const from = msgs.length
    const speechEnd = await speak(pcm)
    const t1 = performance.now() + 9000
    while (performance.now() < t1) {
      await pump(160)
      const got = msgs.slice(from)
      if (got.some((x) => x.m.type === 'metrics' || x.m.type === 'audio_end')) break
    }
    await pump(400)
    return { recs: msgs.slice(from), speechEnd }
  }

  // lead-in: room tone before the first word (gain from the first clip)
  const firstPcm = await tts(sc.turns[0].say, spec.locale)
  if (noise) gain = Math.sqrt(power(new Int16Array(firstPcm.buffer.slice(firstPcm.byteOffset, firstPcm.byteOffset + firstPcm.length - (firstPcm.length % 2)))) / (noiseP * 10 ** (cond.snr! / 10)))
  await pump(900)

  const results: TurnResult[] = []
  let prevOk = true
  for (let ti = 0; ti < sc.turns.length; ti++) {
    const turn = sc.turns[ti]
    const ex = turn.expect
    const { recs: first, speechEnd } = await exchange(turn.say)
    let recs = first
    const heard: string[] = []
    const asked: string[] = []
    let userApproved = false
    let rejected = false
    let unresolved = ''
    const finals = (r: Rec[]) => r.flatMap((x) => (x.m.type === 'final' ? [x.m.text] : []))
    heard.push(...finals(first))
    const pendingOf = (r: Rec[]) => (r.filter((x) => x.m.type === 'pending').at(-1)?.m as Extract<ServerMsg, { type: 'pending' }> | undefined)?.pending ?? null
    const firstAudio = first.find((x) => x.m.type === 'audio')
    const latencyMs = firstAudio ? firstAudio.t - speechEnd : null
    const metrics = first.find((x) => x.m.type === 'metrics')?.m as Extract<ServerMsg, { type: 'metrics' }> | undefined
    const pendFirst = pendingOf(first)
    const expectedEntries = ex.entries ?? []

    // dialogue: the agent asks, the harness answers like a careful shopkeeper
    if (expectedEntries.length) {
      for (let k = 0; k < 5; k++) {
        const entriesNow = recs.flatMap((x) => (x.m.type === 'ops' ? x.m.ops : [])).filter((o) => o.op === 'entry').length
        const pend = pendingOf(recs)
        if (!pend || entriesNow >= expectedEntries.length) break
        const want = expectedEntries[entriesNow]
        const wantName = want.cid === 'new' ? null : spec.customers.find((c) => c.cid === want.cid)?.name
        if (pend.kind === 'confirm') {
          asked.push(`confirm(${pend.name} ${pend.paise! / 100} ${pend.direction})`)
          const match = pend.paise === want.paise && pend.direction === want.direction && (wantName === null || pend.name === wantName)
          const r = await exchange(match ? spec.yes : spec.no)
          recs = recs.concat(r.recs)
          heard.push(...finals(r.recs))
          if (match) userApproved = true
          else { rejected = true; break }
        } else if (pend.kind === 'confusable') {
          asked.push(`confusable(${pend.options?.join('/')})`)
          const r = await exchange(String(want.paise / 100) + '.')
          recs = recs.concat(r.recs)
          heard.push(...finals(r.recs))
        } else if (pend.kind === 'direction' && !asked.some((a) => a.startsWith('direction'))) {
          // the agent asked "credit or payment?" although it was said: answer with the one word
          asked.push(`direction(${pend.name} ${pend.paise! / 100})`)
          const r = await exchange(want.direction === 'credit' ? spec.dirCredit : spec.dirPayment)
          recs = recs.concat(r.recs)
          heard.push(...finals(r.recs))
        } else {
          asked.push(pend.kind)
          unresolved = pend.kind
          break
        }
      }
    }

    const ops = recs.flatMap((x) => (x.m.type === 'ops' ? x.m.ops : []))
    const said = recs.flatMap((x) => (x.m.type === 'say' ? [x.m.text] : []))
    const errors = recs.flatMap((x) => (x.m.type === 'error' ? [x.m.message] : []))
    const saved = ops.flatMap((o) => { const e = entryOf(o); return e ? [e] : [] })
    const newCids = new Map(ops.flatMap((o) => (o.op === 'add_customer' ? [[o.cid, o.name] as const] : [])))
    const amends = ops.flatMap((o) => (o.op === 'amend' ? [o] : []))
    const brief = { entries: saved.map((e) => ({ cid: newCids.has(e.cid) ? `new:${newCids.get(e.cid)}` : e.cid, paise: e.paise, dir: e.direction, promise: e.promise })), amends: amends.map((a) => ({ paise: a.paise, direction: a.direction })), other: ops.filter((o) => !['entry', 'amend', 'add_customer'].includes(o.op)).map((o) => o.op) }

    const r: TurnResult = {
      lang, cond: cond.label, scenario: sc.id, kind: sc.kind, turn: ti, say: turn.say, heard, replied: said, asked, expect: ex,
      got: brief, outcome: 'ok', reason: '', latencyMs, snrDb: metrics?.turn.snrDb ?? null, entryOutcomes: [], dirOk: [], kindOf: 'entry',
    }
    if (errors.length) r.reason += `errors: ${errors.join('; ')} `

    if (ti > 0 && !prevOk) {
      r.outcome = 'skipped'
      r.reason = 'previous turn failed, so this one is not meaningful'
      r.kindOf = ex.amend ? 'amend' : ex.entries ? 'entry' : ex.said ? 'query' : 'pending'
      results.push(r)
      continue
    }

    if (expectedEntries.length) {
      r.kindOf = 'entry'
      const mism: string[] = []
      expectedEntries.forEach((want, i) => {
        const got = saved[i]
        if (!got) { r.entryOutcomes.push('no_save'); r.dirOk.push(false); mism.push(`#${i} not saved${rejected ? ' (readback wrong, user said no)' : unresolved ? ` (agent stuck asking ${unresolved})` : ''}`); return }
        const cidOk = want.cid === 'new' ? newCids.has(got.cid) : got.cid === want.cid
        const ok = cidOk && got.paise === want.paise && got.direction === want.direction && got.promise === want.promise
        r.dirOk.push(got.direction === want.direction)
        if (ok) r.entryOutcomes.push(asked.length ? 'asked_ok' : 'direct_ok')
        else {
          r.entryOutcomes.push(userApproved && asked.length ? 'asked_wrong' : 'silent_wrong')
          mism.push(`#${i} wanted ${want.cid} ${want.paise / 100} ${want.direction}${want.promise ? ' promise' : ''}, saved ${cidOk ? want.cid : 'other customer'} ${got.paise / 100} ${got.direction}${got.promise ? ' promise' : ''}`)
        }
      })
      for (let i = expectedEntries.length; i < saved.length; i++) { r.entryOutcomes.push('silent_wrong'); mism.push(`extra entry saved ${saved[i].paise / 100} ${saved[i].direction}`) }
      const bad = r.entryOutcomes.find((o) => o === 'silent_wrong') ?? r.entryOutcomes.find((o) => o === 'asked_wrong') ?? r.entryOutcomes.find((o) => o === 'no_save')
      r.outcome = bad ?? (r.entryOutcomes.every((o) => o === 'direct_ok') ? 'direct_ok' : 'asked_ok')
      r.reason += mism.join('; ')
    } else if (ex.amend) {
      r.kindOf = 'amend'
      const a = amends[0]
      const good = !!a && (ex.amend.paise === undefined || a.paise === ex.amend.paise) && (ex.amend.direction === undefined || a.direction === ex.amend.direction) && !saved.length
      r.outcome = good ? 'ok' : saved.length || a ? 'silent_wrong' : 'fail'
      if (!good) r.reason += a ? `amend ${JSON.stringify({ paise: a.paise, direction: a.direction })} wanted ${JSON.stringify(ex.amend)}` : saved.length ? 'saved a new entry instead of correcting' : `no amend (said: ${said.join(' | ')}; pending ${JSON.stringify(pendFirst)})`
    } else if (ex.said) {
      r.kindOf = 'query'
      const flat = said.join(' ').replace(/[,\s]/g, '')
      const good = ex.said.every((s) => flat.includes(s)) && !saved.length
      r.outcome = good ? 'ok' : saved.length ? 'silent_wrong' : 'fail'
      if (!good) r.reason += `wanted reply containing ${ex.said.join(',')}, said "${said.join(' | ')}"`
    } else if (ex.pending) {
      r.kindOf = 'pending'
      const good = pendFirst?.kind === ex.pending && !ops.some((o) => o.op === 'entry')
      r.outcome = good ? 'ok' : saved.length ? 'silent_wrong' : 'fail'
      if (!good) r.reason += `wanted ${ex.pending} question, pending ${JSON.stringify(pendFirst)}, said "${said.join(' | ')}"`
    }
    const okish = ['ok', 'direct_ok', 'asked_ok'].includes(r.outcome)
    prevOk = okish
    results.push(r)
  }
  await pump(200)
  ws.close()
  return results
}

// ------------------------------------------------------------------ stats
function wilson(k: number, n: number): [number, number] {
  if (!n) return [0, 0]
  const z = 1.96
  const p = k / n
  const d = 1 + (z * z) / n
  const c = (p + (z * z) / (2 * n)) / d
  const h = (z * Math.sqrt((p * (1 - p)) / n + (z * z) / (4 * n * n))) / d
  return [Math.max(0, c - h), Math.min(1, c + h)]
}
const pct = (k: number, n: number) => (n ? `${((100 * k) / n).toFixed(0)}%` : '-')
const ci = (k: number, n: number) => { const [a, b] = wilson(k, n); return n ? `${(a * 100).toFixed(0)}-${(b * 100).toFixed(0)}` : '-' }
const quant = (xs: number[], q: number) => (xs.length ? [...xs].sort((a, b) => a - b)[Math.min(xs.length - 1, Math.floor(q * xs.length))] : null)

function summarise(rows: TurnResult[]) {
  const live = rows.filter((r) => r.outcome !== 'skipped')
  const entries = live.filter((r) => r.kindOf === 'entry')
  const eo = entries.flatMap((r) => r.entryOutcomes)
  const direct = eo.filter((o) => o === 'direct_ok').length
  const askedOk = eo.filter((o) => o === 'asked_ok').length
  const dirs = entries.flatMap((r) => r.dirOk)
  const amend = live.filter((r) => r.kindOf === 'amend')
  const query = live.filter((r) => r.kindOf === 'query')
  const pend = live.filter((r) => r.kindOf === 'pending')
  const lat = rows.map((r) => r.latencyMs).filter((x): x is number => x !== null)
  return {
    entryN: eo.length, exact: direct + askedOk, direct, askedOk,
    asked: entries.filter((r) => r.asked.length).length, entryTurns: entries.length,
    askedWrong: eo.filter((o) => o === 'asked_wrong').length, noSave: eo.filter((o) => o === 'no_save').length,
    silentWrong: live.filter((r) => r.outcome === 'silent_wrong').reduce((s, r) => s + Math.max(1, r.entryOutcomes.filter((o) => o === 'silent_wrong').length), 0),
    dirN: dirs.length, dirOk: dirs.filter(Boolean).length,
    corrN: amend.length, corrOk: amend.filter((r) => r.outcome === 'ok').length,
    queryN: query.length, queryOk: query.filter((r) => r.outcome === 'ok').length,
    pendN: pend.length, pendOk: pend.filter((r) => r.outcome === 'ok').length,
    skipped: rows.length - live.length,
    p50: quant(lat, 0.5), p95: quant(lat, 0.95), latN: lat.length,
  }
}

// ------------------------------------------------------------------ main
const langs = LANGS.filter((l) => SC.langs[l])
const jobs: { lang: string; sc: Scenario; cond: Cond }[] = []
for (const cond of CONDS) for (const lang of langs) for (const sc of SC.langs[lang].scenarios.slice(0, LIMIT)) jobs.push({ lang, sc, cond })

// estimate streamed audio before touching the network
const texts = new Map<string, { text: string; locale: string }>()
for (const lang of langs) {
  const L = SC.langs[lang]
  for (const sc of L.scenarios.slice(0, LIMIT)) for (const t of sc.turns) {
    texts.set(cacheFile(t.say, L.locale), { text: t.say, locale: L.locale })
    for (const e of t.expect.entries ?? []) texts.set(cacheFile(`${e.paise / 100}.`, L.locale), { text: `${e.paise / 100}.`, locale: L.locale })
  }
  texts.set(cacheFile(L.yes, L.locale), { text: L.yes, locale: L.locale })
  texts.set(cacheFile(L.no, L.locale), { text: L.no, locale: L.locale })
}
const uncached = [...texts.entries()].filter(([f]) => !existsSync(f))
const dur = (text: string, f: string) => (existsSync(f) ? (statSizeSec(f)) : text.length * 0.09)
function statSizeSec(f: string) { return readFileSync(f).length / 32000 }
let estSec = 0
for (const j of jobs) {
  estSec += 0.9
  for (const t of j.sc.turns) estSec += dur(t.say, cacheFile(t.say, SC.langs[j.lang].locale)) + 4.5 // speech + ~4.5 s reply/pause window
  estSec += j.sc.turns.length * 0.25 * 4.5 // allowance for read-back answers
}
console.log(`target ${URL_}`)
console.log(`conditions: ${CONDS.map((c) => c.label).join(', ')} | langs ${langs.join(',')} | ${jobs.length} scenario runs, ${jobs.reduce((s, j) => s + j.sc.turns.length, 0)} turns`)
console.log(`TTS clips: ${texts.size} total, ${uncached.length} to synthesise (cached otherwise)`)
console.log(`estimated streamed audio: ${(estSec / 60).toFixed(1)} min (wall time about ${(estSec / 60 / Math.min(CONC, jobs.length)).toFixed(1)} min at concurrency ${CONC})`)
if (estSec > 40 * 60 && !flag('yes-big')) {
  console.log('ABORT: estimate above 40 minutes of streamed audio; pass --yes-big to run anyway.')
  process.exit(2)
}

// synthesise missing clips (limited concurrency)
{
  const q = [...uncached]
  await Promise.all(Array.from({ length: Math.min(4, q.length) }, async () => {
    while (q.length) { const [, v] = q.shift()!; await synth(v.text, v.locale) }
  }))
}
const tts = (t: string, locale: string) => synth(t, locale)

const t0 = performance.now()
const all: TurnResult[] = []
let streamedMs = 0
let done = 0
const queue = [...jobs]
await Promise.all(Array.from({ length: Math.min(CONC, jobs.length) }, async () => {
  while (queue.length) {
    const j = queue.shift()!
    const s0 = performance.now()
    let rows: TurnResult[]
    try {
      rows = await runScenario(j.lang, SC.langs[j.lang], j.sc, j.cond, tts)
    } catch (e) {
      rows = j.sc.turns.map((t, i) => ({ lang: j.lang, cond: j.cond.label, scenario: j.sc.id, kind: j.sc.kind, turn: i, say: t.say, heard: [], replied: [], asked: [], expect: t.expect, got: null, outcome: 'fail' as Outcome, reason: `harness/connection error: ${e}`, latencyMs: null, snrDb: null, entryOutcomes: t.expect.entries ? t.expect.entries.map(() => 'no_save' as Outcome) : [], dirOk: t.expect.entries ? t.expect.entries.map(() => false) : [], kindOf: (t.expect.amend ? 'amend' : t.expect.entries ? 'entry' : t.expect.said ? 'query' : 'pending') as TurnResult['kindOf'] }))
    }
    streamedMs += performance.now() - s0
    all.push(...rows)
    done++
    const bad = rows.filter((r) => !['ok', 'direct_ok', 'asked_ok', 'skipped'].includes(r.outcome))
    process.stdout.write(`\r${done}/${jobs.length} scenario runs, ${bad.length ? 'last had failures' : 'last ok'}      `)
  }
}))
console.log()

// ------------------------------------------------------------------ report
const keyOf = (r: TurnResult) => `${r.lang}|${r.cond}`
const groups = new Map<string, TurnResult[]>()
for (const r of all) {
  for (const k of [keyOf(r), `ALL|${r.cond}`]) groups.set(k, [...(groups.get(k) ?? []), r])
}
const condOrder = CONDS.map((c) => c.label)
const keys = [...groups.keys()].sort((a, b) => {
  const [la, ca] = a.split('|')
  const [lb, cb] = b.split('|')
  if ((la === 'ALL') !== (lb === 'ALL')) return la === 'ALL' ? 1 : -1
  return la === lb ? condOrder.indexOf(ca) - condOrder.indexOf(cb) : langs.indexOf(la) - langs.indexOf(lb)
})
const summaries: Record<string, ReturnType<typeof summarise>> = {}
const head = ['lang', 'condition', 'exact (95% CI)', 'dir', 'correct.', 'SILENT', 'asked', 'direct/askd', 'lat p50/p95 ms']
const rowsOut: string[][] = []
for (const k of keys) {
  const s = summarise(groups.get(k)!)
  summaries[k] = s
  const [l, c] = k.split('|')
  rowsOut.push([l, c, `${s.exact}/${s.entryN} ${pct(s.exact, s.entryN)} [${ci(s.exact, s.entryN)}]`, pct(s.dirOk, s.dirN), s.corrN ? `${s.corrOk}/${s.corrN}` : '-', String(s.silentWrong), pct(s.asked, s.entryTurns), `${s.direct}/${s.askedOk}`, `${s.p50?.toFixed(0) ?? '-'}/${s.p95?.toFixed(0) ?? '-'}`])
}
const w = head.map((h, i) => Math.max(h.length, ...rowsOut.map((r) => r[i].length)))
const line = (r: string[]) => r.map((c, i) => c.padEnd(w[i])).join('  ')
console.log('\n' + line(head))
console.log(w.map((x) => '-'.repeat(x)).join('  '))
rowsOut.forEach((r, i) => { if (i > 0 && r[0] !== rowsOut[i - 1][0]) console.log(''); console.log(line(r)) })

const failures = all.filter((r) => !['ok', 'direct_ok', 'asked_ok', 'skipped'].includes(r.outcome))
const sw = failures.filter((r) => r.outcome === 'silent_wrong')
console.log(`\n${failures.length} failing turns (${sw.length} silent-wrong), ${all.filter((r) => r.outcome === 'skipped').length} skipped (setup turn failed).`)
for (const r of failures.sort((a, b) => (a.outcome === 'silent_wrong' ? -1 : 0) - (b.outcome === 'silent_wrong' ? -1 : 0))) {
  console.log(`[${r.outcome}] ${r.lang} ${r.cond} ${r.scenario}#${r.turn}: "${r.say}"\n     heard: ${r.heard.join(' || ')}\n     said:  ${r.replied.join(' | ')}\n     ${r.reason}`)
}

const estimateActual = streamedMs / 1000
const ts = new Date().toISOString().replace(/[-:]/g, '').replace(/\..*/, '').replace('T', '_')
const outFile = `eval/results/e2e_${ts}${TAG ? '_' + TAG : ''}.json`
writeFileSync(outFile, JSON.stringify({ url: URL_, conditions: CONDS, langs, streamedSecondsSummed: estimateActual, wallSeconds: (performance.now() - t0) / 1000, summaries, turns: all }, null, 1))
console.log(`\ntotal audio streamed (summed over parallel sockets): ${(estimateActual / 60).toFixed(1)} min, wall ${((performance.now() - t0) / 60000).toFixed(1)} min`)
console.log(`results: ${outFile}`)
process.exit(0)
